import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.DrDMl0tG.js";const b=JSON.parse('{"title":"Asset Credits","description":"","frontmatter":{},"headers":[],"relativePath":"sections/AssetCredits.md","filePath":"sections/AssetCredits.md"}'),s={name:"sections/AssetCredits.md"};function l(h,e,d,i,n,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="asset-credits" tabindex="-1">Asset Credits <a class="header-anchor" href="#asset-credits" aria-label="Permalink to &quot;Asset Credits&quot;">​</a></h1><p>The images and videos on this site are RaiSim simulations rendered with rayrai. Most of the models, textures and skies in them are CC0, which asks for no credit, or RaiSim&#39;s own. The assets below are licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">Creative Commons Attribution 4.0</a> (CC BY 4.0) or ask for credit, and are credited here as their licenses require. The full notices, including every change made to the originals, ship with the assets in the <code>rsc</code> folder of <a href="https://github.com/raisimTech/raisim2Lib" target="_blank" rel="noreferrer">raisim2Lib</a>.</p><h2 id="off-road-buggy-and-race-venue" tabindex="-1">Off-road buggy and race venue <a class="header-anchor" href="#off-road-buggy-and-race-venue" aria-label="Permalink to &quot;Off-road buggy and race venue&quot;">​</a></h2><p>Seen in the off-road clips of the home page, the <a href="./examples/rayrai/rayrai_offroad_buggy.html">Off-Road Buggy example</a> and the <a href="./DeformableTerrain.html">deformable terrain</a> figures. Full notice: <a href="https://github.com/raisimTech/raisim2Lib/blob/HEAD/rsc/offroad_buggy/ATTRIBUTION.md" target="_blank" rel="noreferrer">rsc/offroad_buggy/ATTRIBUTION.md</a>.</p><table tabindex="0"><thead><tr><th>Work</th><th>Author</th><th>Used as</th></tr></thead><tbody><tr><td><a href="https://sketchfab.com/3d-models/sci-fi-buggy-085bd97876a64eacbc041299ac945e9c" target="_blank" rel="noreferrer">&quot;Sci - Fi Buggy&quot;</a></td><td><a href="https://sketchfab.com/tiyamakes" target="_blank" rel="noreferrer">TiyaMakes</a></td><td>buggy body, wheels and steering wheel</td></tr><tr><td><a href="https://sketchfab.com/3d-models/free-coilover-shock-absorber-damper-92e61757780840a683abdd38c4e8a700" target="_blank" rel="noreferrer">&quot;[Free] Coilover Shock Absorber Damper&quot;</a></td><td><a href="https://sketchfab.com/rprispil" target="_blank" rel="noreferrer">Robert Prispilović</a></td><td>dampers</td></tr><tr><td><a href="https://sketchfab.com/3d-models/hay-bales-6b775049e57e4d9da87977905493ebfb" target="_blank" rel="noreferrer">&quot;Hay Bales&quot;</a></td><td><a href="https://sketchfab.com/FrodoUndead" target="_blank" rel="noreferrer">FrodoUndead</a></td><td>hay bales</td></tr><tr><td><a href="https://sketchfab.com/3d-models/water-barriers-b39c313f0b2148dca48bf113529fb06e" target="_blank" rel="noreferrer">&quot;Water Barriers&quot;</a></td><td><a href="https://sketchfab.com/xplanepilot" target="_blank" rel="noreferrer">xplanepilot</a></td><td>track barriers</td></tr><tr><td><a href="https://sketchfab.com/3d-models/porta-potty-b970702ea74a456e89673e73cfb6d873" target="_blank" rel="noreferrer">&quot;Porta Potty&quot;</a></td><td><a href="https://sketchfab.com/foon." target="_blank" rel="noreferrer">Sean Thomas</a></td><td>portable toilets</td></tr><tr><td><a href="https://sketchfab.com/3d-models/bleacher-4960023d1ea340bfb07625aaa7f9713b" target="_blank" rel="noreferrer">&quot;Bleacher&quot;</a></td><td><a href="https://sketchfab.com/JanStano" target="_blank" rel="noreferrer">JanStano</a></td><td>bleachers</td></tr></tbody></table><p>All CC BY 4.0. The models are baked into Z-up meshes in metres with reduced textures; the buggy is split into the links of the simulated chassis, and the coilover is rescaled and split into a damper body and rod. The venue also parks the city cars below.</p><h2 id="city-cars" tabindex="-1">City cars <a class="header-anchor" href="#city-cars" aria-label="Permalink to &quot;City cars&quot;">​</a></h2><p>Seen in the city clips of the home page, the <a href="./examples/rayrai/rayrai_city.html">City</a>, <a href="./examples/rayrai/rayrai_city_from_xml.html">City From XML</a> and <a href="./examples/rayrai/rayrai_offroad_buggy.html">Off-Road Buggy</a> examples, and the README. Full notice: <a href="https://github.com/raisimTech/raisim2Lib/blob/HEAD/rsc/city/ATTRIBUTION.md" target="_blank" rel="noreferrer">rsc/city/ATTRIBUTION.md</a>.</p><table tabindex="0"><thead><tr><th>Work</th><th>Author</th></tr></thead><tbody><tr><td><a href="https://sketchfab.com/3d-models/fairheaven-lt-80-low-poly-model-e2678da920cc4be68dbc193727919ffb" target="_blank" rel="noreferrer">&quot;Fairheaven LT &#39;80 - Low poly model&quot;</a></td><td><a href="https://sketchfab.com/DanielZhabotinsky" target="_blank" rel="noreferrer">Daniel Zhabotinsky</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/fairheaven-sw-84-low-poly-model-aa0becb6e854422596cac6b21bf79787" target="_blank" rel="noreferrer">&quot;Fairheaven SW &#39;84 - Low poly model&quot;</a></td><td><a href="https://sketchfab.com/DanielZhabotinsky" target="_blank" rel="noreferrer">Daniel Zhabotinsky</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/kiri-86-low-poly-model-5c17c582ef9549798f694b660feea42a" target="_blank" rel="noreferrer">&quot;Kiri &#39;86 - Low poly model&quot;</a></td><td><a href="https://sketchfab.com/DanielZhabotinsky" target="_blank" rel="noreferrer">Daniel Zhabotinsky</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/canyon-75-taxi-low-poly-model-9e8f92a215784f3d8aaaaeab1bef54c4" target="_blank" rel="noreferrer">&quot;Canyon &#39;75 Taxi - Low poly model&quot;</a></td><td><a href="https://sketchfab.com/DanielZhabotinsky" target="_blank" rel="noreferrer">Daniel Zhabotinsky</a></td></tr></tbody></table><p>All CC BY 4.0. Each car is baked into one Z-up mesh with 1K textures and a plain car paint, and some get extra paint colours.</p><h2 id="tank-survival-vehicles" tabindex="-1">Tank Survival vehicles <a class="header-anchor" href="#tank-survival-vehicles" aria-label="Permalink to &quot;Tank Survival vehicles&quot;">​</a></h2><p>Seen on the <a href="./examples/rayrai/rayrai_tank_survival.html">Tank Survival</a> and <a href="./WebAssemblySdk.html">WebAssembly SDK</a> pages and in the game on this website. Full notice: <a href="https://github.com/raisimTech/raisim2Lib/blob/HEAD/rsc/tank_survival/ATTRIBUTION.md" target="_blank" rel="noreferrer">rsc/tank_survival/ATTRIBUTION.md</a>.</p><table tabindex="0"><thead><tr><th>Work</th><th>Author</th></tr></thead><tbody><tr><td><a href="https://sketchfab.com/3d-models/80b589fc9c0b4720888b40d01d6e5153" target="_blank" rel="noreferrer">&quot;Leopard 2A4M Main Battle Tank&quot;</a></td><td><a href="https://sketchfab.com/MirzaArrafiERV_45" target="_blank" rel="noreferrer">MirzaArrafiERV_45</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/dfe130dfce724c30958cec51f2bd86b7" target="_blank" rel="noreferrer">&quot;T-72B3 Main Battle Tank&quot;</a></td><td><a href="https://sketchfab.com/MirzaArrafiERV_45" target="_blank" rel="noreferrer">MirzaArrafiERV_45</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/619de9f0908e4c8395fe036ffe6e3884" target="_blank" rel="noreferrer">&quot;Uralvagonzavod T-90AM Main Battle Tank&quot;</a></td><td><a href="https://sketchfab.com/MirzaArrafiERV_45" target="_blank" rel="noreferrer">MirzaArrafiERV_45</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/c12432ada9a84859bc74c3d5ef7046f8" target="_blank" rel="noreferrer">&quot;2S19 MSTA-S Self-Propelled Artillery&quot;</a></td><td><a href="https://sketchfab.com/MirzaArrafiERV_45" target="_blank" rel="noreferrer">MirzaArrafiERV_45</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/16c4113b6592474baa897902e8fbc637" target="_blank" rel="noreferrer">&quot;Russian BMD-2M&quot;</a></td><td><a href="https://sketchfab.com/42manako" target="_blank" rel="noreferrer">42manako</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/24c9a06973a64651a8b0baedee29fd57" target="_blank" rel="noreferrer">&quot;T-14 Armata&quot;</a></td><td><a href="https://sketchfab.com/42manako" target="_blank" rel="noreferrer">42manako</a></td></tr><tr><td><a href="https://sketchfab.com/3d-models/bca9950218c545ecbd70b15704a35bf6" target="_blank" rel="noreferrer">&quot;2S25 Sprut-SD (Armored Warfare)&quot;</a></td><td><a href="https://sketchfab.com/KojfDiscord" target="_blank" rel="noreferrer">KojfDiscord</a></td></tr></tbody></table><p>All CC BY 4.0. Each vehicle is split into hull, turret and gun, rescaled, re-oriented and re-textured at 1K.</p><h2 id="warehouse" tabindex="-1">Warehouse <a class="header-anchor" href="#warehouse" aria-label="Permalink to &quot;Warehouse&quot;">​</a></h2><p>Seen in the <a href="./examples/rayrai/rayrai_warehouse.html">Warehouse example</a>. Full notice: <a href="https://github.com/raisimTech/raisim2Lib/blob/HEAD/rsc/warehouse/ATTRIBUTION.md" target="_blank" rel="noreferrer">rsc/warehouse/ATTRIBUTION.md</a>.</p><table tabindex="0"><thead><tr><th>Work</th><th>Author</th><th>Used as</th></tr></thead><tbody><tr><td><a href="https://sketchfab.com/3d-models/forklift-truck-060f3f8bc7de4e6ca2f348d414702e9d" target="_blank" rel="noreferrer">&quot;Forklift Truck&quot;</a></td><td><a href="https://sketchfab.com/louir-muir" target="_blank" rel="noreferrer">louis-muir</a></td><td>forklift</td></tr><tr><td><a href="https://sketchfab.com/3d-models/pallet-jack-low-poly-55397e1bb66a48bd9d6e1ef93d8456cc" target="_blank" rel="noreferrer">&quot;Pallet Jack (Low Poly)&quot;</a></td><td><a href="https://sketchfab.com/berkgedik" target="_blank" rel="noreferrer">Berk Gedik</a></td><td>pallet jack</td></tr><tr><td><a href="https://sketchfab.com/3d-models/wooden-pallets-dba5c00928cd400796d9f6fffdd724b3" target="_blank" rel="noreferrer">&quot;Wooden Pallets&quot;</a></td><td><a href="https://sketchfab.com/erroratten" target="_blank" rel="noreferrer">Erroratten</a></td><td>pallets</td></tr><tr><td><a href="https://sketchfab.com/3d-models/set-of-cardboard-boxes-8986ba512f704ac5b253286a0d1ad8bb" target="_blank" rel="noreferrer">&quot;Set of Cardboard Boxes&quot;</a></td><td><a href="https://sketchfab.com/notanotherapocalypticco" target="_blank" rel="noreferrer">NotAnotherApocalypticCo.</a></td><td>cartons</td></tr></tbody></table><p>All CC BY 4.0. The models are baked into Z-up meshes in metres, rescaled to real sizes, with their materials converted to metallic-roughness and textures reduced to 1K or 2K.</p><h2 id="ycb-objects" tabindex="-1">YCB objects <a class="header-anchor" href="#ycb-objects" aria-label="Permalink to &quot;YCB objects&quot;">​</a></h2><p>Seen in the <a href="./examples/server/ycb_objects.html">YCB Objects</a>, <a href="./examples/rayrai/rayrai_coacd_mesh_approximation.html">CoACD Mesh Approximation</a>, <a href="./examples/rayrai/rayrai_complete_showcase.html">Complete Showcase</a> and <a href="./examples/rayrai/rayrai_visual_asset_support.html">Visual Asset Support</a> examples and the README: the master chef can, tuna fish can, strawberry, apple and orange of the <a href="https://www.ycbbenchmarks.com/" target="_blank" rel="noreferrer">YCB Object and Model Set</a> (Calli et al., Yale University, Carnegie Mellon University and UC Berkeley), CC BY 4.0. URDF files and convex collision meshes are added for simulation. Full notice: <a href="https://github.com/raisimTech/raisim2Lib/blob/HEAD/rsc/ycb/ATTRIBUTION.md" target="_blank" rel="noreferrer">rsc/ycb/ATTRIBUTION.md</a>.</p><h2 id="metal-rough-spheres" tabindex="-1">Metal-rough spheres <a class="header-anchor" href="#metal-rough-spheres" aria-label="Permalink to &quot;Metal-rough spheres&quot;">​</a></h2><p>Seen in the <a href="./examples/rayrai/rayrai_pbr_material_grid.html">PBR Material Grid example</a>: the glTF sample model <a href="https://github.com/KhronosGroup/glTF-Sample-Assets/tree/main/Models/MetalRoughSpheres" target="_blank" rel="noreferrer">MetalRoughSpheres</a>, © 2017 Analytical Graphics, Inc., by Ed Mackey, CC BY 4.0, rendered unchanged.</p><h2 id="tcp-viewer-icons" tabindex="-1">TCP viewer icons <a class="header-anchor" href="#tcp-viewer-icons" aria-label="Permalink to &quot;TCP viewer icons&quot;">​</a></h2><p>The icons of the <a href="./RayraiTcpViewer.html">TCP viewer</a>&#39;s panels, seen in its screenshots and clips, are <a href="https://www.flaticon.com/uicons" target="_blank" rel="noreferrer">UIcons by Flaticon</a>.</p><h2 id="assets-that-need-no-credit" tabindex="-1">Assets that need no credit <a class="header-anchor" href="#assets-that-need-no-credit" aria-label="Permalink to &quot;Assets that need no credit&quot;">​</a></h2><p>These are free to use without credit; they are listed for their providers&#39; benefit.</p><ul><li>Models, textures and skies from <a href="https://polyhaven.com" target="_blank" rel="noreferrer">Poly Haven</a> (CC0) in the forest, city, warehouse and off-road scenes and the rayrai examples. Powered by Poly Haven.</li><li>Textures from <a href="https://ambientcg.com" target="_blank" rel="noreferrer">ambientCG</a> (CC0) and the traffic cone from <a href="https://www.blendkit.com" target="_blank" rel="noreferrer">BlendKit</a> (CC0).</li><li>The Khronos <a href="https://github.com/KhronosGroup/glTF-Sample-Assets" target="_blank" rel="noreferrer">glTF sample models</a> Flight Helmet, Sci-Fi Helmet, Lantern, Boom Box, Avocado and Water Bottle (CC0).</li><li>Robot models under permissive software licenses: ANYmal and ANYmal C (ANYbotics, BSD-3-Clause), Go1, Minitaur, Kinova, Husky and Robotiq 2F-85 descriptions, the Shadow Hand (Shadow Robot Company, BSD-3-Clause), the JetBot (MIT) and Create 3 (iRobot, BSD-3-Clause) from NVIDIA Isaac Sim&#39;s asset library, and the Gymnasium MJCF models (MIT). Their license files are in their <code>rsc</code> folders.</li></ul>',27)])])}const m=a(s,[["render",l]]);export{b as __pageData,m as default};
